INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('cf93a971-7134-5263-8327-6089f09dbaa9','Mobilidade do tornozelo — após prótese da anca',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/entorse-tornozelo/2026-10-30/mobilidade.png',NULL,'{"posicao_inicial": ["Sentado ou deitado, apoie a perna e o calcanhar confortavelmente, deixando o pé livre para mexer."], "execucao": ["Mova lentamente o pé para cima e para baixo, sem forçar.", "Uma subida e descida completas contam como uma repetição."], "pontos_chave": ["Não desenhe movimentos amplos para dentro nem force a ponta do pé.", "Faça apenas o lado, apoio, amplitude e dose prescritos.", "Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• Sentado ou deitado, apoie a perna e o calcanhar confortavelmente, deixando o pé livre para mexer.

execucao
• Mova lentamente o pé para cima e para baixo, sem forçar.
• Uma subida e descida completas contam como uma repetição.

pontos chave
• Não desenhe movimentos amplos para dentro nem force a ponta do pé.
• Faça apenas o lado, apoio, amplitude e dose prescritos.
• Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Mobilidade / Alongamento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('1cda17f8-1225-53e6-afde-89d81b43b0b9','Isométrico de quadricípite — após prótese da anca',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/gonartrose/2026-10-28/isometrico-quadricipite.png',NULL,'{"posicao_inicial": ["De costas, cabeça apoiada, perna alongada e pequena toalha enrolada debaixo do joelho."], "execucao": ["Contraia a parte anterior da coxa, pressionando suavemente o joelho contra a toalha.", "Mantenha pelo tempo prescrito, relaxe e repita."], "pontos_chave": ["Não levante a bacia nem force a extensão. Não é necessário fazer força máxima.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.", "Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas."], "erros_comuns": ["Usar impulso, prender a respiração ou aumentar a dificuldade sem controlo."], "dicas": ["Respire normalmente e peça ensino da técnica se tiver dúvidas."]}'::jsonb,'posicao inicial
• De costas, cabeça apoiada, perna alongada e pequena toalha enrolada debaixo do joelho.

execucao
• Contraia a parte anterior da coxa, pressionando suavemente o joelho contra a toalha.
• Mantenha pelo tempo prescrito, relaxe e repita.

pontos chave
• Não levante a bacia nem force a extensão. Não é necessário fazer força máxima.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.
• Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.

erros comuns
• Usar impulso, prender a respiração ou aumentar a dificuldade sem controlo.

dicas
• Respire normalmente e peça ensino da técnica se tiver dúvidas.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('5a751445-3699-53d7-9e05-6d3a4bac57ab','Deslizar o calcanhar — após prótese da anca',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/gonartrose/2026-10-28/deslizar-calcanhar.png',NULL,'{"posicao_inicial": ["De costas, cabeça apoiada e pernas numa posição confortável."], "execucao": ["Deslize o calcanhar na direção da bacia, fletindo o joelho dentro da amplitude tolerada.", "Deslize de novo para alongar a perna, sem forçar o fim do movimento."], "pontos_chave": ["O calcanhar mantém contacto com a superfície. A imagem não define a amplitude obrigatória.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.", "Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.", "Não procure a amplitude da imagem: pare no limite de flexão prescrito. Não cruze a linha média."], "erros_comuns": ["Usar impulso, prender a respiração ou aumentar a dificuldade sem controlo."], "dicas": ["Respire normalmente e peça ensino da técnica se tiver dúvidas."]}'::jsonb,'posicao inicial
• De costas, cabeça apoiada e pernas numa posição confortável.

execucao
• Deslize o calcanhar na direção da bacia, fletindo o joelho dentro da amplitude tolerada.
• Deslize de novo para alongar a perna, sem forçar o fim do movimento.

pontos chave
• O calcanhar mantém contacto com a superfície. A imagem não define a amplitude obrigatória.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.
• Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.
• Não procure a amplitude da imagem: pare no limite de flexão prescrito. Não cruze a linha média.

erros comuns
• Usar impulso, prender a respiração ou aumentar a dificuldade sem controlo.

dicas
• Respire normalmente e peça ensino da técnica se tiver dúvidas.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Mobilidade / Alongamento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('9a8d9031-85eb-55b9-8cca-6a991ebee288','Elevação dos calcanhares com apoio — PTA',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Peso Corporal']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/gonartrose/2026-10-28/calcanhares.png',NULL,'{"posicao_inicial": ["De pé no chão plano, pés paralelos e mãos num apoio estável."], "execucao": ["Eleve os dois calcanhares lentamente, mantendo a parte anterior dos pés apoiada.", "Baixe os calcanhares com controlo até ao chão."], "pontos_chave": ["Distribua o peso pelos dois pés. Não usar um degrau nesta variante.", "Reduza a amplitude ou a dose se o joelho ou o tornozelo agravarem.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.", "Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas."], "erros_comuns": ["Usar impulso, prender a respiração ou aumentar a dificuldade sem controlo."], "dicas": ["Respire normalmente e peça ensino da técnica se tiver dúvidas."]}'::jsonb,'posicao inicial
• De pé no chão plano, pés paralelos e mãos num apoio estável.

execucao
• Eleve os dois calcanhares lentamente, mantendo a parte anterior dos pés apoiada.
• Baixe os calcanhares com controlo até ao chão.

pontos chave
• Distribua o peso pelos dois pés. Não usar um degrau nesta variante.
• Reduza a amplitude ou a dose se o joelho ou o tornozelo agravarem.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.
• Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.

erros comuns
• Usar impulso, prender a respiração ou aumentar a dificuldade sem controlo.

dicas
• Respire normalmente e peça ensino da técnica se tiver dúvidas.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('d90579a6-8a5f-58ee-b88e-941bdf36832c','Abdução da anca em pé com apoio — PTA, se autorizada',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/abducao-sem-carga.png',NULL,'{"posicao_inicial": ["De pé junto a uma cadeira firme, segurando o encosto. Tronco vertical, bacia nivelada e pés paralelos."], "execucao": ["Afaste ligeiramente a perna a exercitar para o lado, mantendo o pé para a frente.", "Regresse até à posição inicial, sem cruzar a linha do corpo."], "pontos_chave": ["Comece com amplitude pequena e sem elástico.", "O apoio na outra perna também exige esforço: se agravar os sintomas, escolha uma opção deitada ou sentada.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.", "Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.", "Não faça se recebeu indicação para evitar abdução ativa ou resistida, por exemplo após reparação muscular/tendinosa."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'posicao inicial
• De pé junto a uma cadeira firme, segurando o encosto. Tronco vertical, bacia nivelada e pés paralelos.

execucao
• Afaste ligeiramente a perna a exercitar para o lado, mantendo o pé para a frente.
• Regresse até à posição inicial, sem cruzar a linha do corpo.

pontos chave
• Comece com amplitude pequena e sem elástico.
• O apoio na outra perna também exige esforço: se agravar os sintomas, escolha uma opção deitada ou sentada.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.
• Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.
• Não faça se recebeu indicação para evitar abdução ativa ou resistida, por exemplo após reparação muscular/tendinosa.

erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('feefa641-c97a-5361-a75a-d76ac43a014c','Extensão curta da anca em pé — PTA, se autorizada',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/coxartrose/2026-10-28/extensao.png',NULL,'{"posicao_inicial": ["De pé diante de uma bancada estável, mãos apoiadas, pés paralelos e tronco direito."], "execucao": ["Leve ligeiramente a perna a exercitar para trás, com o joelho praticamente estendido.", "Regresse devagar até à posição inicial."], "pontos_chave": ["Movimento curto na anca. Não arquear a região lombar, inclinar o tronco ou rodar a bacia.", "Use apoio suficiente para manter o equilíbrio.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.", "Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.", "Não ultrapasse a extensão autorizada. Confirme esta direção de movimento com a equipa antes de iniciar."], "erros_comuns": ["Forçar o movimento, rodar a bacia, usar impulso ou prender a respiração."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'posicao inicial
• De pé diante de uma bancada estável, mãos apoiadas, pés paralelos e tronco direito.

execucao
• Leve ligeiramente a perna a exercitar para trás, com o joelho praticamente estendido.
• Regresse devagar até à posição inicial.

pontos chave
• Movimento curto na anca. Não arquear a região lombar, inclinar o tronco ou rodar a bacia.
• Use apoio suficiente para manter o equilíbrio.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.
• Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.
• Não ultrapasse a extensão autorizada. Confirme esta direção de movimento com a equipa antes de iniciar.

erros comuns
• Forçar o movimento, rodar a bacia, usar impulso ou prender a respiração.

dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('02232666-17cc-5de8-87d3-33d7f694eb3b','Equilíbrio numa perna com apoio — PTA',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/apoio-unipodal.png',NULL,'{"posicao_inicial": ["De pé ao lado de uma cadeira firme, em chão plano e com olhos abertos. Uma mão apoiada no encosto."], "execucao": ["Transfira o peso para a perna a exercitar e eleve ligeiramente o outro pé.", "Mantenha a bacia nivelada pelo tempo prescrito. Volte aos dois apoios e descanse."], "pontos_chave": ["Ajuste o apoio da mão e o tempo à tolerância. Não deixe a bacia cair.", "Não progrida automaticamente para olhos fechados ou superfície instável.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.", "Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'posicao inicial
• De pé ao lado de uma cadeira firme, em chão plano e com olhos abertos. Uma mão apoiada no encosto.

execucao
• Transfira o peso para a perna a exercitar e eleve ligeiramente o outro pé.
• Mantenha a bacia nivelada pelo tempo prescrito. Volte aos dois apoios e descanse.

pontos chave
• Ajuste o apoio da mão e o tempo à tolerância. Não deixe a bacia cair.
• Não progrida automaticamente para olhos fechados ou superfície instável.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.
• Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.

erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Propriocepção / Equilíbrio']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('6b4967cc-eda6-566f-a6c7-b9e8bfd91dd0','Ponte bilateral curta — PTA, se autorizada',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Peso Corporal']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/ponte-bilateral.png',NULL,'{"posicao_inicial": ["De costas num tapete, joelhos fletidos, pés apoiados à largura da bacia e braços ao lado do corpo."], "execucao": ["Empurre o chão com os dois pés e eleve a bacia apenas até à altura tolerada.", "Regresse lentamente, sem arquear excessivamente a região lombar."], "pontos_chave": ["Distribua o esforço pelos dois pés e não deixe os joelhos cair para dentro.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.", "Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.", "Não ultrapasse a extensão autorizada. Confirme esta direção de movimento com a equipa antes de iniciar."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'posicao inicial
• De costas num tapete, joelhos fletidos, pés apoiados à largura da bacia e braços ao lado do corpo.

execucao
• Empurre o chão com os dois pés e eleve a bacia apenas até à altura tolerada.
• Regresse lentamente, sem arquear excessivamente a região lombar.

pontos chave
• Distribua o esforço pelos dois pés e não deixe os joelhos cair para dentro.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.
• Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.
• Não ultrapasse a extensão autorizada. Confirme esta direção de movimento com a equipa antes de iniciar.

erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('a10d89a3-e00c-552e-a5f2-ad668ddf378f','Degrau baixo com apoio — reforço após PTA',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Peso Corporal']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/step-up.png',NULL,'{"posicao_inicial": ["Diante de um degrau baixo, firme e antiderrapante, com corrimão ao lado. Pé da perna a exercitar totalmente apoiado no degrau."], "execucao": ["Suba com controlo, sem impulso excessivo da perna de trás.", "Desça devagar e repita na altura e amplitude prescritas."], "pontos_chave": ["Mantenha o joelho orientado com o pé e a bacia controlada.", "Use o corrimão. Não existe uma altura obrigatória; não use bancos instáveis.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.", "Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'posicao inicial
• Diante de um degrau baixo, firme e antiderrapante, com corrimão ao lado. Pé da perna a exercitar totalmente apoiado no degrau.

execucao
• Suba com controlo, sem impulso excessivo da perna de trás.
• Desça devagar e repita na altura e amplitude prescritas.

pontos chave
• Mantenha o joelho orientado com o pé e a bacia controlada.
• Use o corrimão. Não existe uma altura obrigatória; não use bancos instáveis.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.
• Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.

erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('c1c3b7a0-e8b7-5b04-af05-24cb842709e6','Abdução da anca com elástico — PTA, se autorizada',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Elásticos']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://nxfnzzcuqzxmzsihbrtp.supabase.co/storage/v1/object/public/wo-exercises/59eaa0f7-3ac0-4508-afb0-4513b5a8e547.jpg',NULL,'{"posicao_inicial": ["De pé com apoio estável disponível, elástico leve nos tornozelos e pés paralelos à largura da bacia."], "execucao": ["Afaste lateralmente a perna a exercitar na amplitude prescrita, sem inclinar o tronco.", "Regresse devagar até à largura inicial; não deixe a perna cruzar a linha do corpo."], "pontos_chave": ["A imagem demonstra a variante sem apoio; use apoio da mão se necessário.", "Aumente a resistência só mantendo controlo da bacia e boa tolerância.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.", "Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.", "Não faça se recebeu indicação para evitar abdução ativa ou resistida, por exemplo após reparação muscular/tendinosa."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'posicao inicial
• De pé com apoio estável disponível, elástico leve nos tornozelos e pés paralelos à largura da bacia.

execucao
• Afaste lateralmente a perna a exercitar na amplitude prescrita, sem inclinar o tronco.
• Regresse devagar até à largura inicial; não deixe a perna cruzar a linha do corpo.

pontos chave
• A imagem demonstra a variante sem apoio; use apoio da mão se necessário.
• Aumente a resistência só mantendo controlo da bacia e boa tolerância.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.
• Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.
• Não faça se recebeu indicação para evitar abdução ativa ou resistida, por exemplo após reparação muscular/tendinosa.

erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('f3216f72-a36d-5ded-be6a-85b4508715bb','Extensão da anca com elástico — PTA, se autorizada',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Elásticos']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/coxartrose/2026-10-28/extensao-elastico.png',NULL,'{"posicao_inicial": ["De pé diante de apoio estável, elástico em laço acima dos tornozelos, pés paralelos e tronco direito."], "execucao": ["Leve a perna a exercitar um pouco para trás, contra uma resistência ligeira.", "Regresse lentamente, sem deixar o elástico puxar a perna de forma brusca."], "pontos_chave": ["A amplitude mantém-se curta e tolerada. Não compensar com a região lombar.", "Comece com elástico leve e bem colocado, sem apertar a pele.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.", "Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.", "Não ultrapasse a extensão autorizada. Confirme esta direção de movimento com a equipa antes de iniciar."], "erros_comuns": ["Forçar o movimento, rodar a bacia, usar impulso ou prender a respiração."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'posicao inicial
• De pé diante de apoio estável, elástico em laço acima dos tornozelos, pés paralelos e tronco direito.

execucao
• Leve a perna a exercitar um pouco para trás, contra uma resistência ligeira.
• Regresse lentamente, sem deixar o elástico puxar a perna de forma brusca.

pontos chave
• A amplitude mantém-se curta e tolerada. Não compensar com a região lombar.
• Comece com elástico leve e bem colocado, sem apertar a pele.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.
• Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.
• Não ultrapasse a extensão autorizada. Confirme esta direção de movimento com a equipa antes de iniciar.

erros comuns
• Forçar o movimento, rodar a bacia, usar impulso ou prender a respiração.

dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('22d6986f-9f4e-5911-a719-3c03ddf58ac3','Bicicleta estática — após prótese da anca',ARRAY['Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Máquina']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://nxfnzzcuqzxmzsihbrtp.supabase.co/storage/v1/object/public/wo-exercises/75536e39-ff44-4a86-97cd-5c4300457826.jpg',NULL,'{"dicas": ["Confirmar os ajustes antes de iniciar o tempo prescrito.", "Manter respiração regular.", "Usar a intensidade indicada no plano, não apenas a sensação de velocidade."], "execucao": ["Iniciar com resistência baixa e cadência confortável.", "Pedalar de forma contínua, mantendo joelhos e pés alinhados.", "Aplicar a intensidade e a duração prescritas.", "Reduzir gradualmente a intensidade antes de parar."], "erros_comuns": ["Selim demasiado baixo ou alto.", "Joelhos desviarem-se para dentro ou para fora.", "Apoiar peso excessivo nas mãos.", "Começar com resistência elevada."], "pontos_chave": ["Bacia estável no selim.", "Joelhos acompanham a direção dos pés.", "Ombros relaxados.", "Cadência regular.", "Parar se sentir dor aguda.", "A carga, a amplitude e a dose são individuais. Reduza se piorarem o inchaço, o sono ou a manhã seguinte.", "Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.", "Só após autorização, entrada/saída seguras e ajuste do assento para respeitar o limite de flexão da anca."], "posicao_inicial": ["Ajustar a altura do selim para manter ligeira flexão do joelho no ponto mais baixo do pedal.", "Ajustar a distância ao guiador sem obrigar a arredondar excessivamente o tronco.", "Colocar os pés centrados e seguros nos pedais."]}'::jsonb,'dicas
• Confirmar os ajustes antes de iniciar o tempo prescrito.
• Manter respiração regular.
• Usar a intensidade indicada no plano, não apenas a sensação de velocidade.

execucao
• Iniciar com resistência baixa e cadência confortável.
• Pedalar de forma contínua, mantendo joelhos e pés alinhados.
• Aplicar a intensidade e a duração prescritas.
• Reduzir gradualmente a intensidade antes de parar.

erros comuns
• Selim demasiado baixo ou alto.
• Joelhos desviarem-se para dentro ou para fora.
• Apoiar peso excessivo nas mãos.
• Começar com resistência elevada.

pontos chave
• Bacia estável no selim.
• Joelhos acompanham a direção dos pés.
• Ombros relaxados.
• Cadência regular.
• Parar se sentir dor aguda.
• A carga, a amplitude e a dose são individuais. Reduza se piorarem o inchaço, o sono ou a manhã seguinte.
• Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.
• Só após autorização, entrada/saída seguras e ajuste do assento para respeitar o limite de flexão da anca.

posicao inicial
• Ajustar a altura do selim para manter ligeira flexão do joelho no ponto mais baixo do pedal.
• Ajustar a distância ao guiador sem obrigar a arredondar excessivamente o tronco.
• Colocar os pés centrados e seguros nos pedais.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Cardiovascular']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('8a841088-f449-5ecc-8eec-f8df982ad9c2','Transferência de peso com apoio — após PTA',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/transferencia-peso.png',NULL,'{"posicao_inicial": ["De pé diante de apoio estável, mãos apoiadas e ambos os pés no chão à largura da bacia."], "execucao": ["Desloque uma pequena parte do peso para uma perna, mantendo os dois pés apoiados.", "Regresse ao centro e alterne, sem deixar a bacia cair para o lado."], "pontos_chave": ["Movimento pequeno. Não ficar pendurado numa só anca.", "Reduza o deslocamento ou substitua a opção se provocar dor.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.", "Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'posicao inicial
• De pé diante de apoio estável, mãos apoiadas e ambos os pés no chão à largura da bacia.

execucao
• Desloque uma pequena parte do peso para uma perna, mantendo os dois pés apoiados.
• Regresse ao centro e alterne, sem deixar a bacia cair para o lado.

pontos chave
• Movimento pequeno. Não ficar pendurado numa só anca.
• Reduza o deslocamento ou substitua a opção se provocar dor.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.
• Após prótese da anca, faça apenas se autorizado para a sua cirurgia e dentro da carga e amplitude prescritas.

erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Propriocepção / Equilíbrio']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('21ec509f-445a-5261-8c84-5f4255f455cd','Isométrico glúteo deitado — após PTA',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/protese-anca/2026-10-30/gluteos.png',NULL,'{"posicao_inicial": ["Deitado de costas numa superfície firme e confortável, cabeça apoiada e pernas afastadas numa largura confortável."], "execucao": ["Contraia suavemente as nádegas, sem levantar a bacia.", "Mantenha o tempo prescrito, relaxe e repita."], "pontos_chave": ["Não é uma ponte. Não prenda a respiração nem empurre para provocar movimento da anca.", "Respeite a carga, os movimentos e a dose prescritos para a sua cirurgia."], "erros_comuns": ["Forçar dor, perder controlo ou ultrapassar as restrições prescritas."], "dicas": ["Respire normalmente. Peça ensino presencial da técnica."]}'::jsonb,'posicao inicial
• Deitado de costas numa superfície firme e confortável, cabeça apoiada e pernas afastadas numa largura confortável.

execucao
• Contraia suavemente as nádegas, sem levantar a bacia.
• Mantenha o tempo prescrito, relaxe e repita.

pontos chave
• Não é uma ponte. Não prenda a respiração nem empurre para provocar movimento da anca.
• Respeite a carga, os movimentos e a dose prescritos para a sua cirurgia.

erros comuns
• Forçar dor, perder controlo ou ultrapassar as restrições prescritas.

dicas
• Respire normalmente. Peça ensino presencial da técnica.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('6da72c45-3ec1-5f36-b3ea-f7f6ff2afa7b','Sentar e levantar com braços da cadeira — após PTA',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/protese-anca/2026-10-30/cadeira.png',NULL,'{"posicao_inicial": ["Cadeira firme, estável e com braços, na altura indicada. Pés apoiados; perna operada ligeiramente à frente se isso facilitar."], "execucao": ["Aproxime-se da borda com controlo e apoie as mãos nos braços da cadeira.", "Empurre os apoios para se levantar, sem puxar pelas canadianas. Para sentar, recue até sentir a cadeira e desça com controlo."], "pontos_chave": ["Respeite o limite de flexão que lhe foi indicado. Não use uma cadeira baixa, instável ou que deslize.", "No início pode ser apenas treino de transferência, com ajuda; as séries de reforço só quando autorizadas e toleradas.", "Respeite a carga, os movimentos e a dose prescritos para a sua cirurgia."], "erros_comuns": ["Forçar dor, perder controlo ou ultrapassar as restrições prescritas."], "dicas": ["Respire normalmente. Peça ensino presencial da técnica."]}'::jsonb,'posicao inicial
• Cadeira firme, estável e com braços, na altura indicada. Pés apoiados; perna operada ligeiramente à frente se isso facilitar.

execucao
• Aproxime-se da borda com controlo e apoie as mãos nos braços da cadeira.
• Empurre os apoios para se levantar, sem puxar pelas canadianas. Para sentar, recue até sentir a cadeira e desça com controlo.

pontos chave
• Respeite o limite de flexão que lhe foi indicado. Não use uma cadeira baixa, instável ou que deslize.
• No início pode ser apenas treino de transferência, com ajuda; as séries de reforço só quando autorizadas e toleradas.
• Respeite a carga, os movimentos e a dose prescritos para a sua cirurgia.

erros comuns
• Forçar dor, perder controlo ou ultrapassar as restrições prescritas.

dicas
• Respire normalmente. Peça ensino presencial da técnica.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('2ff7680f-100b-53be-b3e2-c18d02c8c219','Marcha com duas canadianas — após PTA',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/protese-anca/2026-10-30/marcha.png',NULL,'{"posicao_inicial": ["Canadianas ajustadas, ponteiras íntegras, piso plano e livre de obstáculos; respeite o apoio autorizado."], "execucao": ["Conforme ensinado, avance as duas canadianas um pouco, depois a perna operada e depois a outra.", "Faça passos curtos e pare para descansar antes de coxear mais ou perder equilíbrio."], "pontos_chave": ["A imagem mostra a posição dos apoios; não define a percentagem de carga nem substitui o ensino da sequência.", "Se lhe foi indicado não apoiar ou usar andarilho, siga essa técnica específica. Não inicie escadas sozinho.", "Respeite a carga, os movimentos e a dose prescritos para a sua cirurgia."], "erros_comuns": ["Forçar dor, perder controlo ou ultrapassar as restrições prescritas."], "dicas": ["Respire normalmente. Peça ensino presencial da técnica."]}'::jsonb,'posicao inicial
• Canadianas ajustadas, ponteiras íntegras, piso plano e livre de obstáculos; respeite o apoio autorizado.

execucao
• Conforme ensinado, avance as duas canadianas um pouco, depois a perna operada e depois a outra.
• Faça passos curtos e pare para descansar antes de coxear mais ou perder equilíbrio.

pontos chave
• A imagem mostra a posição dos apoios; não define a percentagem de carga nem substitui o ensino da sequência.
• Se lhe foi indicado não apoiar ou usar andarilho, siga essa técnica específica. Não inicie escadas sozinho.
• Respeite a carga, os movimentos e a dose prescritos para a sua cirurgia.

erros comuns
• Forçar dor, perder controlo ou ultrapassar as restrições prescritas.

dicas
• Respire normalmente. Peça ensino presencial da técnica.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Cardiovascular']::text[]);
INSERT INTO public.protocols_catalog (id,region,name,kind,is_active,sort_order,data) VALUES ('47971d8a-62f5-533d-b5f3-e982857aa666','anca','Artroplastia Total da Anca (Prótese Total) — recuperação domiciliária','cirurgico',TRUE,14,'{"version": 1, "versao_clinica": "2026-10-30", "contextos": ["Casa", "Clínica", "Ginásio"], "fontes": [{"title": "AAOS — exercício após prótese total da anca", "url": "https://www.orthoinfo.org/recovery/total-hip-replacement-exercise-guide/"}, {"title": "AAOS — atividade e precauções individualizadas", "url": "https://www.orthoinfo.org/recovery/activities-after-hip-replacement"}, {"title": "NICE NG157 — reabilitação após artroplastia primária", "url": "https://www.nice.org.uk/guidance/ng157/chapter/Recommendations"}, {"title": "Cambridge University Hospitals — cuidados e exercícios", "url": "https://www.cuh.nhs.uk/patient-information/hip-replacement-total-advice-and-exercises-following/"}], "documento_base": "Exercícios - Anca - Recomendações Pós PTA.pdf — pasta fornecida pelo utilizador", "status_revisao": "revisto_com_limites_e_restricoes_individuais_2026-10-30", "nota_clinica": "PTA primária após alta, sem complicações, com carga e precauções confirmadas. Três fases por critérios, seis opções manuais por fase. Não aplicar automaticamente a revisão, fratura, osteotomia, reparação de abdutores, luxação ou complicações.", "dose": "Doses iniciais práticas, não dose ótima validada. Reforço progressivo 3×12 quando tolerado; início reduzido, mobilidade 1×10, isométricos 5×10 s e equilíbrio 3×20 s. A seleção e as restrições individuais prevalecem."}'::jsonb);
INSERT INTO public.protocol_phases (id,protocol_id,phase_order,name,anchor_kind,anchor_from,anchor_to,data) VALUES ('b0856c7e-bb3b-51e4-8970-1f0e99312736','47971d8a-62f5-533d-b5f3-e982857aa666',1,'1 — Proteção, autonomia e ativação inicial','evolucao_clinica',NULL,NULL,'{"nota_ancora": "Por critérios e autorização clínica; respeitar também cicatrização e tempos de proteção cirúrgicos.", "objetivos": [{"id": "o1", "label": "Recuperar movimentos simples, transferências e marcha com os auxiliares indicados."}], "permitido": ["Apenas movimentos e carga expressamente autorizados para esta cirurgia."], "contraindicacoes": ["Não ultrapassar restrições de carga, amplitude ou reparações associadas.", "Não avançar perante sinais de alarme ou deterioração persistente."], "hep": ["Seis opções por fase; fazer apenas as selecionadas."], "recomendacoes": [{"title": "O seu plano", "text": "Faça apenas os exercícios selecionados e a dose prescrita. As seis opções não são obrigatórias na mesma sessão. Este plano é para a recuperação após a alta; não substitui as instruções da equipa que o operou."}, {"title": "Proteção da prótese", "text": "Confirme quanto pode apoiar e quais os movimentos temporariamente limitados. Não aumente o apoio, a amplitude ou a resistência por iniciativa própria. As restrições variam com a cirurgia; não há uma regra de 90 graus ou de cruzar pernas igual para todas as pessoas. Se recebeu essas restrições, cumpra-as pelo período indicado."}, {"title": "Marcha e canadianas", "text": "Use o andarilho ou as canadianas prescritas e previamente ajustadas. Faça trajetos curtos, com passos controlados. Com duas canadianas e apoio autorizado: avance os apoios, depois a perna operada e depois a outra, conforme o ensino recebido. Não abandone os auxiliares enquanto coxear, perder equilíbrio ou tiver restrição de carga."}, {"title": "Sentar e levantar", "text": "Prefira uma cadeira firme, estável e com braços, com a altura indicada pela equipa. Empurre os braços da cadeira para se levantar; não puxe pelas canadianas. Ao sentar, recue até sentir a cadeira atrás das pernas e desça com controlo. Coloque a perna operada ligeiramente à frente se isso facilitar, dentro das suas restrições."}, {"title": "Escadas", "text": "Treine primeiro com um profissional. Use o corrimão e o auxiliar na outra mão, conforme ensinado. Habitualmente, ao subir avança primeiro a perna não operada; ao descer, o auxiliar e a perna operada. Um degrau de cada vez. A técnica muda se não puder apoiar, tiver limitações na outra perna ou não houver corrimão: peça instruções próprias."}, {"title": "Cama, carro e atividades diárias", "text": "Entre e saia da cama e do carro com a técnica ensinada, mantendo o tronco e as pernas alinhados dentro dos limites prescritos. Para mudar de direção, dê pequenos passos em vez de rodar sobre o pé fixo. Use ajuda para vestir-se e calçar-se se necessário. As posições para dormir dependem das suas indicações; não force uma posição dolorosa."}, {"title": "Conforto e inchaço", "text": "Intercale atividade com pausas e eleve confortavelmente a perna se ajudar no inchaço. Se aliviar, aplique frio protegido por toalha durante 10–15 minutos, sem adormecer e sem molhar ou pressionar a ferida. Confirme antes se tiver alterações de sensibilidade, circulação ou intolerância ao frio. Não massaje a ferida nem a barriga da perna inchada ou dolorosa."}, {"title": "Ferida e medicação", "text": "Siga os cuidados do penso e da ferida e a medicação da alta. Não interrompa o anticoagulante nem altere as meias de compressão prescritas sem orientação. Os exercícios do tornozelo não substituem a prevenção de trombose prescrita."}, {"title": "Como fazer e ajustar", "text": "Faça movimentos lentos e respire normalmente. Pare perante dor súbita, sensação de deslocação, falha ou perda de controlo. Se a dor, o inchaço ou a marcha estiverem claramente piores depois da sessão ou na manhã seguinte, reduza e contacte a equipa para ajustar. Não avance de fase só porque passaram dias ou semanas."}, {"title": "Sinais de alarme", "text": "Ligue 112 perante falta de ar súbita, dor no peito ou desmaio. Procure avaliação urgente perante dor súbita forte na anca com incapacidade de apoiar, deformidade, queda com dor importante, pé frio/pálido ou dor e inchaço novos na barriga da perna. Contacte a equipa cirúrgica no próprio dia perante febre, drenagem da ferida, vermelhidão crescente ou dor em agravamento."}], "recomendacoes_clinicas": [{"title": "Confirmar antes de prescrever", "text": "Registar lado, data, indicação da PTA, via cirúrgica, fixação, carga permitida, limites de movimento, reparações associadas, cicatrização, comorbilidades e auxiliares. Não basta selecionar a fase. A ausência de dados não equivale a ausência de restrições. Programa para PTA primária sem complicações; revisão/fratura/osteotomia/reparação de abdutores/luxação exigem adaptação específica."}, {"title": "Precauções por cirurgia, não universais", "text": "Cumprir as indicações do cirurgião e os tempos de proteção dos tecidos, mesmo com boa função. Via posterior pode ter restrições prescritas de flexão/adução/rotação interna, sobretudo combinadas; via anterior pode limitar extensão/rotação externa; vias laterais e reparações de abdutores podem limitar abdução ativa ou resistida. Estes são exemplos para confirmar, não regras automáticas pela via. Não impor 90 graus a todos nem cancelar uma restrição por critérios funcionais."}, {"title": "Exercícios e carga", "text": "Todos opcionais. Apoio unipodal, gémeos, cadeira e degrau só com carga autorizada. Não selecionar abdução ativa/resistida nem extensão ou ponte sem autorização para essa direção e fase. Após cirurgia evitar alongamentos de fim de amplitude, figura 4, pigeon e mobilizações forçadas do programa de coxartrose. Não fazer elevação da perna estendida de rotina no início."}, {"title": "Dose e progressão", "text": "Doses práticas individualizáveis, não um ensaio validado de 3 fases/6 opções. Início com volume baixo; força até 3×12 se tolerada e autorizada; reduzir séries/repetições se necessário. Na mobilidade usar 1×10; isométricos 5×10 s; equilíbrio 3×20 s com apoio. Progressão depende de função, resposta, cicatrização e autorização, sem semanas fixas ou limiar numérico universal de dor."}, {"title": "Cuidados e referenciação", "text": "Não substituir anticoagulação/profilaxia individual por exercícios. Não massajar suspeita de trombose. Dor nova/crescente, claudicação ou perda de função relacionadas com a prótese justificam contacto/referenciação cirúrgica; urgência se suspeita de luxação, fratura, infeção ou tromboembolismo. Não definir automaticamente alta de condução ou desporto por semanas."}], "criterios_progressao": [{"id": "p1", "texto": "Transferências e marcha curta seguras com o auxiliar e a carga prescritos."}, {"id": "p2", "texto": "Ativação e mobilidade toleradas, ferida e sintomas com evolução acompanhada; equipa autoriza exercícios em pé e direções selecionadas."}], "objetivos_serie": [], "recommendations_scope": "47971d8a-62f5-533d-b5f3-e982857aa666:b0856c7e-bb3b-51e4-8970-1f0e99312736", "revisao_cientifica": "2026-10-30"}'::jsonb);
INSERT INTO public.protocol_phases (id,protocol_id,phase_order,name,anchor_kind,anchor_from,anchor_to,data) VALUES ('ac7f31f6-6d48-5178-8ab0-486d0272f058','47971d8a-62f5-533d-b5f3-e982857aa666',2,'2 — Recuperar força, apoio e controlo','evolucao_clinica',NULL,NULL,'{"nota_ancora": "Por critérios e autorização clínica; respeitar também cicatrização e tempos de proteção cirúrgicos.", "objetivos": [{"id": "o1", "label": "Melhorar o controlo nas tarefas habituais dentro das restrições."}], "permitido": ["Apenas movimentos e carga expressamente autorizados para esta cirurgia."], "contraindicacoes": ["Não ultrapassar restrições de carga, amplitude ou reparações associadas.", "Não avançar perante sinais de alarme ou deterioração persistente."], "hep": ["Seis opções por fase; fazer apenas as selecionadas."], "recomendacoes": [{"title": "O seu plano", "text": "Faça apenas os exercícios selecionados e a dose prescrita. As seis opções não são obrigatórias na mesma sessão. Este plano é para a recuperação após a alta; não substitui as instruções da equipa que o operou."}, {"title": "Restrições e apoio", "text": "Confirme quanto pode apoiar e quais os movimentos temporariamente limitados. Não aumente o apoio, a amplitude ou a resistência por iniciativa própria. As restrições variam com a cirurgia; não há uma regra de 90 graus ou de cruzar pernas igual para todas as pessoas. Se recebeu essas restrições, cumpra-as pelo período indicado. Use o andarilho ou as canadianas prescritas e previamente ajustadas. Faça trajetos curtos, com passos controlados. Com duas canadianas e apoio autorizado: avance os apoios, depois a perna operada e depois a outra, conforme o ensino recebido. Não abandone os auxiliares enquanto coxear, perder equilíbrio ou tiver restrição de carga."}, {"title": "Reforço e equilíbrio", "text": "Reforço habitualmente em dias alternados, com a dose prescrita e apoio firme. Só faça afastamento da perna, extensão da anca ou apoio numa perna se autorizados. Pode manter as mãos apoiadas; não precisa de fechar os olhos."}, {"title": "Cuidados diários", "text": "Prefira uma cadeira firme, estável e com braços, com a altura indicada pela equipa. Empurre os braços da cadeira para se levantar; não puxe pelas canadianas. Ao sentar, recue até sentir a cadeira atrás das pernas e desça com controlo. Coloque a perna operada ligeiramente à frente se isso facilitar, dentro das suas restrições. Entre e saia da cama e do carro com a técnica ensinada, mantendo o tronco e as pernas alinhados dentro dos limites prescritos. Para mudar de direção, dê pequenos passos em vez de rodar sobre o pé fixo. Use ajuda para vestir-se e calçar-se se necessário. As posições para dormir dependem das suas indicações; não force uma posição dolorosa."}, {"title": "Ferida, medicação e conforto", "text": "Siga os cuidados do penso e da ferida e a medicação da alta. Não interrompa o anticoagulante nem altere as meias de compressão prescritas sem orientação. Os exercícios do tornozelo não substituem a prevenção de trombose prescrita. Intercale atividade com pausas e eleve confortavelmente a perna se ajudar no inchaço. Se aliviar, aplique frio protegido por toalha durante 10–15 minutos, sem adormecer e sem molhar ou pressionar a ferida. Confirme antes se tiver alterações de sensibilidade, circulação ou intolerância ao frio. Não massaje a ferida nem a barriga da perna inchada ou dolorosa."}, {"title": "Resposta ao exercício", "text": "Faça movimentos lentos e respire normalmente. Pare perante dor súbita, sensação de deslocação, falha ou perda de controlo. Se a dor, o inchaço ou a marcha estiverem claramente piores depois da sessão ou na manhã seguinte, reduza e contacte a equipa para ajustar. Não avance de fase só porque passaram dias ou semanas."}, {"title": "Sinais de alarme", "text": "Ligue 112 perante falta de ar súbita, dor no peito ou desmaio. Procure avaliação urgente perante dor súbita forte na anca com incapacidade de apoiar, deformidade, queda com dor importante, pé frio/pálido ou dor e inchaço novos na barriga da perna. Contacte a equipa cirúrgica no próprio dia perante febre, drenagem da ferida, vermelhidão crescente ou dor em agravamento."}], "recomendacoes_clinicas": [{"title": "Confirmar antes de prescrever", "text": "Registar lado, data, indicação da PTA, via cirúrgica, fixação, carga permitida, limites de movimento, reparações associadas, cicatrização, comorbilidades e auxiliares. Não basta selecionar a fase. A ausência de dados não equivale a ausência de restrições. Programa para PTA primária sem complicações; revisão/fratura/osteotomia/reparação de abdutores/luxação exigem adaptação específica."}, {"title": "Precauções por cirurgia, não universais", "text": "Cumprir as indicações do cirurgião e os tempos de proteção dos tecidos, mesmo com boa função. Via posterior pode ter restrições prescritas de flexão/adução/rotação interna, sobretudo combinadas; via anterior pode limitar extensão/rotação externa; vias laterais e reparações de abdutores podem limitar abdução ativa ou resistida. Estes são exemplos para confirmar, não regras automáticas pela via. Não impor 90 graus a todos nem cancelar uma restrição por critérios funcionais."}, {"title": "Exercícios e carga", "text": "Todos opcionais. Apoio unipodal, gémeos, cadeira e degrau só com carga autorizada. Não selecionar abdução ativa/resistida nem extensão ou ponte sem autorização para essa direção e fase. Após cirurgia evitar alongamentos de fim de amplitude, figura 4, pigeon e mobilizações forçadas do programa de coxartrose. Não fazer elevação da perna estendida de rotina no início."}, {"title": "Dose e progressão", "text": "Doses práticas individualizáveis, não um ensaio validado de 3 fases/6 opções. Início com volume baixo; força até 3×12 se tolerada e autorizada; reduzir séries/repetições se necessário. Na mobilidade usar 1×10; isométricos 5×10 s; equilíbrio 3×20 s com apoio. Progressão depende de função, resposta, cicatrização e autorização, sem semanas fixas ou limiar numérico universal de dor."}, {"title": "Cuidados e referenciação", "text": "Não substituir anticoagulação/profilaxia individual por exercícios. Não massajar suspeita de trombose. Dor nova/crescente, claudicação ou perda de função relacionadas com a prótese justificam contacto/referenciação cirúrgica; urgência se suspeita de luxação, fratura, infeção ou tromboembolismo. Não definir automaticamente alta de condução ou desporto por semanas."}], "criterios_progressao": [{"id": "p1", "texto": "Tarefas selecionadas com controlo e sem aumento persistente de dor, edema ou claudicação."}, {"id": "p2", "texto": "Força e equilíbrio em melhoria; cicatrização e proteção dos tecidos compatíveis, e autorização para resistência/degrau/bicicleta."}], "objetivos_serie": [], "recommendations_scope": "47971d8a-62f5-533d-b5f3-e982857aa666:ac7f31f6-6d48-5178-8ab0-486d0272f058", "revisao_cientifica": "2026-10-30"}'::jsonb);
INSERT INTO public.protocol_phases (id,protocol_id,phase_order,name,anchor_kind,anchor_from,anchor_to,data) VALUES ('5cec9a4a-f629-52c0-bb9a-8dc5c7c61a3b','47971d8a-62f5-533d-b5f3-e982857aa666',3,'3 — Reforço progressivo e manutenção funcional','evolucao_clinica',NULL,NULL,'{"nota_ancora": "Por critérios e autorização clínica; respeitar também cicatrização e tempos de proteção cirúrgicos.", "objetivos": [{"id": "o1", "label": "Aumentar a capacidade para caminhar, escadas e atividades importantes."}], "permitido": ["Apenas movimentos e carga expressamente autorizados para esta cirurgia."], "contraindicacoes": ["Não ultrapassar restrições de carga, amplitude ou reparações associadas.", "Não avançar perante sinais de alarme ou deterioração persistente."], "hep": ["Seis opções por fase; fazer apenas as selecionadas."], "recomendacoes": [{"title": "O seu plano", "text": "Faça apenas os exercícios selecionados e a dose prescrita. As seis opções não são obrigatórias na mesma sessão. Este plano é para a recuperação após a alta; não substitui as instruções da equipa que o operou."}, {"title": "Restrições ainda em vigor", "text": "Confirme quanto pode apoiar e quais os movimentos temporariamente limitados. Não aumente o apoio, a amplitude ou a resistência por iniciativa própria. As restrições variam com a cirurgia; não há uma regra de 90 graus ou de cruzar pernas igual para todas as pessoas. Se recebeu essas restrições, cumpra-as pelo período indicado."}, {"title": "Frequência e progressão", "text": "Força habitualmente em 2–3 dias por semana, alternados. Aumente uma variável de cada vez: repetições, resistência ou duração. Mantenha os auxiliares se indicados. Se três séries forem excessivas, peça uma dose menor."}, {"title": "Caminhada, escadas e bicicleta", "text": "Mantenha caminhadas toleradas e progrida gradualmente. O degrau de exercício é diferente da técnica inicial de escadas com canadianas. Bicicleta só após autorização, com assento ajustado para respeitar o limite de flexão e entrada/saída seguras."}, {"title": "Regresso às atividades", "text": "Retome as atividades autorizadas aos poucos. Condução, natação, impacto e desporto precisam de decisão própria. Não entre em piscina antes de a ferida estar encerrada e de receber autorização."}, {"title": "Resposta e cuidados", "text": "Faça movimentos lentos e respire normalmente. Pare perante dor súbita, sensação de deslocação, falha ou perda de controlo. Se a dor, o inchaço ou a marcha estiverem claramente piores depois da sessão ou na manhã seguinte, reduza e contacte a equipa para ajustar. Não avance de fase só porque passaram dias ou semanas. Siga os cuidados do penso e da ferida e a medicação da alta. Não interrompa o anticoagulante nem altere as meias de compressão prescritas sem orientação. Os exercícios do tornozelo não substituem a prevenção de trombose prescrita."}, {"title": "Sinais de alarme", "text": "Ligue 112 perante falta de ar súbita, dor no peito ou desmaio. Procure avaliação urgente perante dor súbita forte na anca com incapacidade de apoiar, deformidade, queda com dor importante, pé frio/pálido ou dor e inchaço novos na barriga da perna. Contacte a equipa cirúrgica no próprio dia perante febre, drenagem da ferida, vermelhidão crescente ou dor em agravamento."}], "recomendacoes_clinicas": [{"title": "Confirmar antes de prescrever", "text": "Registar lado, data, indicação da PTA, via cirúrgica, fixação, carga permitida, limites de movimento, reparações associadas, cicatrização, comorbilidades e auxiliares. Não basta selecionar a fase. A ausência de dados não equivale a ausência de restrições. Programa para PTA primária sem complicações; revisão/fratura/osteotomia/reparação de abdutores/luxação exigem adaptação específica."}, {"title": "Precauções por cirurgia, não universais", "text": "Cumprir as indicações do cirurgião e os tempos de proteção dos tecidos, mesmo com boa função. Via posterior pode ter restrições prescritas de flexão/adução/rotação interna, sobretudo combinadas; via anterior pode limitar extensão/rotação externa; vias laterais e reparações de abdutores podem limitar abdução ativa ou resistida. Estes são exemplos para confirmar, não regras automáticas pela via. Não impor 90 graus a todos nem cancelar uma restrição por critérios funcionais."}, {"title": "Exercícios e carga", "text": "Todos opcionais. Apoio unipodal, gémeos, cadeira e degrau só com carga autorizada. Não selecionar abdução ativa/resistida nem extensão ou ponte sem autorização para essa direção e fase. Após cirurgia evitar alongamentos de fim de amplitude, figura 4, pigeon e mobilizações forçadas do programa de coxartrose. Não fazer elevação da perna estendida de rotina no início."}, {"title": "Dose e progressão", "text": "Doses práticas individualizáveis, não um ensaio validado de 3 fases/6 opções. Início com volume baixo; força até 3×12 se tolerada e autorizada; reduzir séries/repetições se necessário. Na mobilidade usar 1×10; isométricos 5×10 s; equilíbrio 3×20 s com apoio. Progressão depende de função, resposta, cicatrização e autorização, sem semanas fixas ou limiar numérico universal de dor."}, {"title": "Cuidados e referenciação", "text": "Não substituir anticoagulação/profilaxia individual por exercícios. Não massajar suspeita de trombose. Dor nova/crescente, claudicação ou perda de função relacionadas com a prótese justificam contacto/referenciação cirúrgica; urgência se suspeita de luxação, fratura, infeção ou tromboembolismo. Não definir automaticamente alta de condução ou desporto por semanas."}], "criterios_progressao": [{"id": "p1", "texto": "Rotina útil e sustentável, com controlo funcional e sem deterioração persistente."}, {"id": "p2", "texto": "Reavaliar objetivos, auxiliares e restrições com a equipa; conclusão desta fase não autoriza corrida, impacto ou desporto."}], "objetivos_serie": [], "recommendations_scope": "47971d8a-62f5-533d-b5f3-e982857aa666:5cec9a4a-f629-52c0-bb9a-8dc5c7c61a3b", "revisao_cientifica": "2026-10-30"}'::jsonb);
